describe('403 Error Handling - Access Denied Page', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display access denied page when 403 error is returned', () => {
    cy.intercept('GET', '/api/protected-resource', {
      statusCode: 403,
      body: {
        error: 'Forbidden',
        message: 'Access denied'
      }
    }).as('forbiddenRequest');

    cy.get('[data-testid="access-protected-button"]').click();
    cy.wait('@forbiddenRequest');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Access Denied');
    cy.get('[data-testid="error-message"]').should('contain', '403');
    cy.get('[data-testid="error-description"]').should('contain', 'You do not have permission');
  });

  it('should display access denied page with custom error message from server', () => {
    const customErrorMessage = 'Your subscription has expired. Please renew to access this resource.';

    cy.intercept('GET', '/api/premium-feature', {
      statusCode: 403,
      body: {
        error: 'Forbidden',
        message: customErrorMessage,
        code: 'SUBSCRIPTION_EXPIRED'
      }
    }).as('premiumRequest');

    cy.get('[data-testid="premium-feature-button"]').click();
    cy.wait('@premiumRequest');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', customErrorMessage);
    cy.get('[data-testid="error-code"]').should('contain', 'SUBSCRIPTION_EXPIRED');
  });

  it('should provide navigation option to return to home from access denied page', () => {
    cy.intercept('GET', '/api/admin-panel', {
      statusCode: 403,
      body: {
        error: 'Forbidden',
        message: 'Admin access required'
      }
    }).as('adminRequest');

    cy.get('[data-testid="admin-button"]').click();
    cy.wait('@adminRequest');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="return-home-button"]').should('be.visible').click();
    cy.url().should('eq', Cypress.config().baseUrl + '/');
  });

  it('should handle 403 error during form submission', () => {
    cy.intercept('POST', '/api/submit-form', {
      statusCode: 403,
      body: {
        error: 'Forbidden',
        message: 'You cannot perform this action'
      }
    }).as('formSubmit');

    cy.get('[data-testid="form-input"]').type('test data');
    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="access-denied-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Access Denied');
  });

  it('should handle multiple 403 errors gracefully', () => {
    cy.intercept('GET', '/api/resource-1', {
      statusCode: 403,
      body: { error: 'Forbidden' }
    }).as('request1');

    cy.intercept('GET', '/api/resource-2', {
      statusCode: 403,
      body: { error: 'Forbidden' }
    }).as('request2');

    cy.get('[data-testid="load-resource-1"]').click();
    cy.wait('@request1');
    cy.get('[data-testid="access-denied-page"]').should('be.visible');

    cy.get('[data-testid="return-home-button"]').click();
    cy.get('[data-testid="load-resource-2"]').click();
    cy.wait('@request2');
    cy.get('[data-testid="access-denied-page"]').should('be.visible');
  });
});
